--- 初始化卡池
---@param data any
function UIBattlingPlayReminderDialog:InitSkillCardPool(data)
    data = {
        r2 = 
        {
            [1] = "1_1_2",
            [2] = "2_2_1",
            [3] = "1_2_1",
        },
        r1 = 
        {
            [1] = "1_1_1",
            [2] = "2_1_1",
            [3] = "1_1_1",
        },
    }
    
    self.LT_CardPool:FillSkillCardOriginData(data)      -- 记录原始数据，重新刷新的时候会用到
    self.LT_CardPool:FillSkillCardShowSequence(data)    -- 设置卡牌信息
    self.LT_CardPool:ReloadSkillCardPoolListData()      -- 加载卡牌预制体
end

--- 重置卡池
function UIBattlingPlayReminderDialog:SetSkillCardDefault()
    self.LT_CardPool:SetSkillCardPoolDataListDefault()
    self.LT_CardPool:ResetSkillCardPushSequence()
    self.LT_CardPool:ReloadSkillCardPoolListData()
end

--- 初始化行动点技能卡
function UIBattlingPlayReminderDialog:InitActionPointCard()
    self.listActionPointCard = {}
    local compArr = self.RT_SkillCardSmallRoot:GetComponentsInChildren(typeof(CS.Engine.Modules.LuaBehaviour))
    for i = 0, compArr.Length - 1 do
        if not isNull(compArr[i]) then
            compArr[i]:Init()
            table.insert(self.listActionPointCard, compArr[i].Env)
        end
    end
    self:SetActionPointCardDefault()
end

---设置行动点技能卡为默认状态
function UIBattlingPlayReminderDialog:SetActionPointCardDefault()
    self.actionPointId = 0
    if self.listActionPointCard then
        for i, v in ipairs(self.listActionPointCard) do
            local card = v
            card:SetSequeneSkillCardDefaut()
            card:SetSkillCardShowState(true)
        end
    end
end

--- 播放合卡动画
function UIBattlingPlayReminderDialog:PlayUnitCardAnimation()
    self.co_animation = cs_coroutine.start(function()
        while true do
            self:SetActionPointCardDefault()        -- 重置行动点
            self:SetSkillCardDefault()              -- 重置卡池
            cs_coroutine.yield_return(self.LT_CardPool:ShowSkillCardsPool())           -- 卡牌入场动画
            CoYield(0.2)    -- 延迟点击
            cs_coroutine.yield_return(self:PlayAnimationFingerPoint({1,2}))    -- 点击
            self:ShowActionPointCard({1,2})         -- 出牌
            CoYield(0.2)    -- 延迟规整
            self.LT_CardPool:SkillCardArrange(1,2)  -- 卡池规整
            CoYield(0.12)   -- 等待规整完毕
            CoYield(0.2)    -- 延迟合卡
            cs_coroutine.yield_return(self.LT_CardPool:SkillCardUnit({s={2,1},d={1,1}}))   -- 合卡，注意合卡的时候pos[1]是序号，pos[2]是行
            CoYield(0.2)    -- 延迟合卡
            cs_coroutine.yield_return(self.LT_CardPool:SkillCardUnit({s={1,1},d={1,2}}))   -- 合卡
            CoYield(1)      -- 等待到下一轮
        end
    end)
end

--- 播放手指点击的动画
---@param pos any
function UIBattlingPlayReminderDialog:PlayAnimationFingerPoint(pos)
    local aimLine = self.LT_CardPool:SelectSkillCardAimLine(pos[1])
    if IsNull(aimLine[pos[2]].luaBehaviour) then
        self.RT_FingerNode.transform.position = Vector3.New(99999, 99999)
        return
    end
    local skillCard = aimLine[pos[2]].luaBehaviour.Env
    if IsNull(skillCard) then
        self.RT_FingerNode.transform.position = Vector3.New(99999, 99999)
        return
    end

    if isNotNull(self.co_fingerAnimation) then
        cs_coroutine.stop(self.co_fingerAnimation)
        self.co_fingerAnimation = nil
    end

    local transSkillCard = skillCard.controller.transform

    if not IsNull(self.RT_FingerNode) then
        KTool.SetParent(self.RT_FingerNode.gameObject, self.RT_SkillCardPool.gameObject)
        self.RT_FingerNode.transform.position = transSkillCard.position or Vector3.New(99999, 99999)
    end
    
    -- print("->PlayAnimationFingerPoint:", position, not isNull(position))
    if not IsNull(self.Animator_FingerNode) then
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))  -- 手指出现以后等0.5s，让玩家看清
        self.Animator_FingerNode.enabled = not isNull(transSkillCard.position)
        self.Animator_FingerNode:Play("Play", 0, 0)                 -- 播放动画
        -- 0.3s后自动隐藏
        self.co_fingerAnimation = cs_coroutine.start(function()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
            self.RT_FingerNode.transform.position = Vector3.New(99999, 99999)
        end)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.15)) -- 动画开始0.15s后手指达到点击的位置
    end
end

--- 使用卡牌，飞到行动点区域里
---@param pos any
function UIBattlingPlayReminderDialog:ShowActionPointCard(pos)
    self.LT_CardPool:SkillCardUsed(pos[1], pos[2])
    self.actionPointId = self.actionPointId + 1-- 更新 出牌序列 Id
    for i = 1, table.count(self.listActionPointCard) do
        local actionPointCard = self.listActionPointCard[i]
        if actionPointCard and (not actionPointCard:GetCardUseState()) then
            local cardData = {
                cardData = self.LT_CardPool:GetSkillCardData(pos[1], pos[2]),
                targetId = 1,
                sequenceId = self.actionPointId,
                isLock = false,
            }
            local position = self.LT_CardPool:GetSkillCardWorldPos(pos[1], pos[2])
            actionPointCard:ShowSequeneSkillCard(cardData, position)
            break
        end
    end
end

return UIBattlingPlayReminderDialog
